import subprocess
from pathlib import Path

def backup_directory(source: Path, output: Path) -> bool:
    """Backup seguro usando subprocess.run sin shell."""
    try:
        result = subprocess.run(
            ['tar', 'czf', str(output), '-C', str(source.parent), source.name],
            capture_output=True,
            text=True,
            timeout=3600  # 1 hora timeout
        )

        if result.returncode == 0:
            print(f'✓ Backup creado: {output}')
            return True
        else:
            print(f'✗ Backup falló: {result.stderr}')
            return False

    except subprocess.TimeoutExpired:
        print('✗ Backup excedió el timeout de 1 hora')
        return False

    except FileNotFoundError:
        print('✗ tar no está instalado')
        return False

def grep_pattern(pattern: str, filename: Path) -> list[str]:
    """grep seguro sin shell injection."""
    result = subprocess.run(
        ['grep', '-E', pattern, str(filename)],
        capture_output=True,
        text=True,
        check=False  # grep retorna 1 si no hay matches (no es error)
    )

    if result.returncode == 0:
        return result.stdout.splitlines()
    elif result.returncode == 1:
        return []  # no matches
    else:
        raise RuntimeError(f'grep falló: {result.stderr}')

